import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"卷五（序卦）","description":"伊川易傳 - 卷五（序卦）","frontmatter":{"title":"卷五（序卦）","description":"伊川易傳 - 卷五（序卦）"},"headers":[],"relativePath":"classics/yichuan/006.md","filePath":"classics/yichuan/006.md"}'),s={name:"classics/yichuan/006.md"};function i(c,p,n,l,o,_){return t(),e("div",null,[...p[0]||(p[0]=[r('<h1 id="卷五-序卦" tabindex="-1">卷五（序卦） <a class="header-anchor" href="#卷五-序卦" aria-label="Permalink to “卷五（序卦）”">​</a></h1><p>第一段</p><p>有天地，然後萬物生焉。①盈天地之間者唯萬物，故受之以屯。屯者，盈也。屯者，物之始生也。②物生必蒙，故受之以蒙。蒙者，蒙也，物之穉也。③物穉不可不養也，故受之以需。需者，飲食之道也。④飲食必有訟，故受之以訟。訟必有眾起，故受之以師，師者，眾也。⑤眾必有所比，故受之以比。比者，比也。比必有所畜，故受之以小畜。⑥物畜然後有禮，故受之以履。履而泰然後安，故受之以泰。泰者，通也。⑦物不可以終通，故受之以否。物不可以終否，故受之以同人。⑧與人同者，物必歸焉，故受之以大有。有大者不可以盈，故受之以謙。⑨有大而能謙必豫，故受之以豫。豫必有隨，故受之以隨。⑩以喜隨人者必有事，故受之以蠱。蠱者，事也。⑾有事而後可大，故受之以臨。臨者，大也。物大然後可觀，故受之以觀。⑿可觀而後有所合，故受之以噬嗑。嗑者，合也。物不可以苟合而已，故受之以賁。賁者，飾也。⒀致飾然後亨則盡矣，故受之以剝。剝者，剝也。物不可以終盡剝，窮上反下，故受之以復。⒁復則不妄矣，故受之以無妄。有無妄，然後可畜，故受之以大畜。⒂物畜然後可養，故受之以頤。頤者，養也。不養則不可動，故受之以大過。⒃物不可以終過，故受之以坎。坎者，陷也。陷必有所麗，故受之以離。離者，麗也。⒄</p><h3 id="註釋" tabindex="-1">註釋 <a class="header-anchor" href="#註釋" aria-label="Permalink to “註釋”">​</a></h3><p>①天地：此天地指六十四卦中的乾坤。以“天地”生萬物說明乾坤為六十四卦之首的原因。萬物：指自然界萬物，此以“萬物”說明六十四卦，“二篇之策萬有一千五百二十，當萬之數”。</p><p>②盈：滿。受：繼，承繼。屯：卦名。屯本義從屮從一，屮即草，一為地，故有草木茁芽於地之義。《屯》卦下震上坎，坎為雨，震為雷，雷雨動盪，其氣充塞。故屯為“盈”。又震為乾剛坤柔始交，故屯為“物之始生”。</p><p>③蒙：卦名。蒙本義是冢上草木，有覆蓋之義。此通萌，鄭玄曰：“齊人謂萌為蒙”，即指幼小之貌。物之初生幼小是未開著，故蒙為矇昧。穉，一本作“稺”、“稚”。古三字通，有幼稚之義。</p><p>④需：卦名。通雩，本義指求雨之祭，引申為需求。《需》下乾上坎，坎為水，乾為天，雲上於天，待時而落，故曰需有待、求雨之義。求雨為保豐年，而飲食有所依賴，故需又為“飲食之道”。</p><p>⑤訟：卦名。《訟》上乾為天，下坎為水，天在上，水在下，天與水違行，故有爭訟之義。師：卦名。師為軍旅之名，古二千五百人為師，師有眾義。《師》下坎上坤，坤為眾，坎為眾。《國語·晉語》：“坎，勞也，水也，眾也。”故師為眾。</p><p>⑥比：卦名。一指周代社會基層組織，五家為比，比有親密無間之義，《比》卦象是水在地上，有親比之義。畜：一本作“蓄”，有畜養之義。小畜，為卦名。《小畜》＄一陰五陽，有一陰畜養五陽之義。陰為小，故曰小畜。</p><p>⑦履：卦名。履本指鞋，有踐履之義，《履》卦上乾為天，下兌為澤，天高在上，澤卑在下，上下尊卑分明，故履為禮。《荀子》雲：“禮者，人之所履也。”帛《易》履皆作“禮”。禮，指上下尊卑之等。李鼎祚《周易集解》、王弼《周易略例卦略》在“故受之以履”之後有“履者，禮也”。泰：卦名。帛《易》“泰”作“柰”。《泰》下乾上坤，乾陽下降，坤陰上升，故有陰陽交通之義，正如《彖》所言：“天地交而萬物通也。”</p><p>⑧否：卦名。帛《易》“否”作“婦”，《否》與《泰》相反，《否》上乾為天，下坤為地，天地陰陽不交通，故否有不通之義。如《彖》所言：“天地不交而萬物不通也。”同人：卦名。人即仁。同人即同仁，《同人》下離上乾，乾為天，離為火，天陽在上，離火炎上，故有志向相同之義。</p><p>⑨大有：卦名。古稱豐年曰有，大豐年曰大有。《大有》一陰擁有五陽，大而富有，即《彖》所謂“柔得尊位，而上下應之，曰大有”。陽為大。謙：卦名。《謙》下艮上坤，艮山高而處地下，故有謙退之義。</p><p>⑩豫：卦名。豫本指象大，引申為娛樂，《豫》下坤上震，坤為地，震為雷，雷出地奮，萬物順性而動，故有喜樂之義。隨：卦名。《隨》下震上兌，震為雷在下，兌為澤在上，雷藏於澤中，隨時休息，故有隨從之義。</p><p>⑾蠱：卦名。蠱字本義為器皿食物腐敗生蟲，有敗壞之義。《蠱》下巽上艮，艮為山，巽為風，風落山，其木摧壞，故有敗壞之義。又艮為少男，巽為長女，有女惑男之象，萬事從惑而起，故以蠱為事，蠱為事，蓋假借“故”，非蠱字有“事”之訓。王引之曰：“蠱之言，故也。《尚書大傳》雲：‘乃命五史。以書五帝之蠱事。’蠱事猶故事也。”</p><p>⑿臨：卦名。帛易《臨》卦作“林”，從爻畫看《臨》二剛臨四柔，“剛浸而長”，故《臨》剛有長大之義。觀：卦名。《觀》與《臨》相反，《觀》二陽在上，陽為大，故“物大然後可觀”。</p><p>⒀噬嗑：卦名。噬嗑本義指嘴裡有食物而咬合，《噬嗑》＄上下兩陽，中一陽即是嘴裡食物之象，此卦下震上離，離為電、震為雷、雷動而威，電閃而明，雷電相合，故有“合”之義。苟：但。《賁》：卦名。《賁》卦剛柔相錯而文飾，故賁有飾之義。</p><p>⒁剝：卦名。剝有剝落之義。《剝》下坤上艮，艮為山，坤為地，山高反附於地故有剝落之義。又《剝》＄一陽於五陰之上，故有五陰剝落一陽之義。窮上反下：窮盡於上必復返於下。窮上，指《剝》一陽居上而窮盡。反下，指《復》卦一陽復一初爻。反，復。《復》＄一陽於五陰之下，有一陽復返之義。</p><p>⒂復則不妄：案《繫辭》“復以自知”。自知而不妄，不妄即不妄行。《無妄》下震上乾，乾為天，震為雷，天下有雷動，故為不妄動。畜，本又作“蓄”，有積聚；蓄養之義。《大畜》下乾上艮，艮為山，乾為天，天在山中，天至大，山靜止，山靜止畜養至大，故為大畜。</p><p>⒃頤：原指人兩腮。《頤》下震上艮，艮為止，震為動，上止下動。口腔之象，從卦畫言《頤》＄上下二陽中四陰，外實中虛。像口腔，食物由口而入以養生，故頤有“養”之義。大過：指大的過失，《大過》下巽上兌，兌為澤，巽為木，澤滅木象故有過，從爻畫看《大過》＄中四陽上下兩陰，中間陽盛，上下弱，即本末弱，故為大過，陽為大。</p><p>⒄陷：通險。《坎》上下皆坎，坎陽陷於陰中故曰陷。麗：依附。《離》卦上下皆離，離陰依附於陽，故離為麗。</p><p>第二段</p><p>有天地然後有萬物。有萬物，然後有男女，有男女，然後有夫婦。有夫婦，然後有父子。有父子，然後有君臣。有君臣，然後有上下。有上下，然後禮儀有所錯。①夫婦之道，不可以不久也，故受之以恆。恆者，久也。物不可以久居其所，故受之以遯。遯者，退也。②物不可以終遯，故受之以大壯。物不可以終壯，故受之以晉。晉者，進也。③進必有所傷，故受之以明夷。夷者，傷也。傷於外者必反一於家，故受之以家人。④家道窮必乖，故受之以睽。睽者，乖也。乖必有難，故受之以蹇。蹇者，難也。⑤物不可以終難，故受之以解。解者，緩也。緩必有所失，故受之以損，損而不已必益，故受之以益。⑥益而不已必決，故受之以夬。夬者，決也。決必有遇，故受之以姤。姤者，遇也。⑦物相遇而後聚，故受之以萃。萃者，聚也。聚而上者謂之升。故受之以升。⑧升而不已必困，故受之以困。困乎上者必反下，故受之以井。井道不可不革，故受之以革。⑨革物者莫若鼎，故受之以鼎。主器者莫若長子，故受之以震。震者，動也。⑩物不可以終動，止之，故受之以艮。艮者，止也。物不可以終止，故受之以漸。漸者，進也。進必有所歸，故受之以歸妹。⑾得其所歸者必大，故受之以豐。豐者，大也。窮大者必失其居，故受之以旅。⑿旅而無所容，故受之以巽。巽者，入也。入而後說之，故受之以兌。兌者，說也。⒀說而後散之，故受之以渙。渙者，離也。物不可以終離，故受之以節，節而信之，故受之以中孚。⒁有其信者必行之，故受之以小過。有過物者必濟，故受之以既濟。物不可窮也，故受之以未濟。終焉。⒂</p><h3 id="註釋-1" tabindex="-1">註釋 <a class="header-anchor" href="#註釋-1" aria-label="Permalink to “註釋”">​</a></h3><p>①此句就《鹹》而言。《鹹》下艮上兌，兌為少女，艮為少男，故稱“男女”。《鹹》“柔上而剛下，二氣感應”，故有“夫婦”之象。艮兌為乾坤求索而生,故曰“父子”。乾坤有尊卑上下，故曰“君臣”“上下”。錯。設置。</p><p>②恆：恆久。《恆》下巽上震，巽為風，震為雷，雷風相與而有恆久之義。遯：通“豚”，謂小豬。《周易》古經“遯”字皆為此義。而《易傳》訓遯為“退”。《遯》下艮上乾，艮為山，乾為天，山高上逼，天遠山而退去，故遯為退，從爻畫看，《遯》＄二陰在四陽之下，有漸長趨勢，陽將退去，故曰退。</p><p>③大壯：此卦四陽盛長而壯大，故先儒多訓壯為大。依《繫辭》“日中則昃，月盈則食”之理，其《大壯》四陽盛長已過半，不久當止。故有止義。《雜卦》“大壯則止”是其確證。晉，有漸進之義。《晉》下坤上離，坤為地，離為日，日出地上，漸進上長，又從爻畫看，“柔進而上行”，故晉有“進”義。</p><p>④明夷：有光明受傷之義。《明夷》與《晉》相反，《晉》是日出地上，《明夷》是日入地中，其光明受傷，故“明夷”有明傷之義。傷於外：《晉》離日在外，進極而傷入其內（變《明夷》）。反其家：《家人》離日在內。家人：指一家之人。《家人》下離上巽，離為火，巽為風，風火相與，有家人之義，又《家人》二五得正相應，二為女在內，五為男在外，男女正，故有家人之義。</p><p>⑤家道窮：指室家至親，過而失節。乖：離散。睽：本義指目不相視，引申為乖異離散，《睽》下兌上離，離為火，兌為澤，火炎上，澤潤下，二者相違背，故有“乖”之義。蹇：本指腿跛，行動不便，此引申為難，《蹇》下艮上坎，艮為山，坎為水，水為山所阻不得下流，故有“難”義。</p><p>⑥解：有緩解之義。《解》下坎上震，坎為雨，震為雷，雷震天上，雨落地下，故有緩解之義。損，減損。《損》下兌上艮，艮為山，兌為澤，澤深山高有損深而增高之義。從爻畫看，《損》＄“損下益上”，故有減損之義。《益》與《損》相反，益，有增益之義，指上增益下，《益》下震上巽，巽為風，震為雷，雷風相與而增益，從爻畫看，《益》＄“損上益下”，故有增益之義。</p><p>⑦決：潰決，決斷。夬：朱駿聲訓本義為“＄”，“象環缺之形”。在《易傳》，“夬”訓之決。《夬》卦下乾上兌，乾為天，兌為澤，澤上於天，勢必下流而散，有決之義，又從爻畫看，《夬》＄一陰在五陽之上，有陽盛和決去一陰之象。決必有所遇：以陽決陰必有所喜遇。姤：相遇之義。《姤》下巽上乾，巽為風，乾為天，風行天下，無所不遇，故為遇，從爻畫看，《姤》＄一陰在下與五陽相遇，故姤有“遇”之義。</p><p>⑧萃：會聚之義。《萃》下坤上兌，坤為地，兌為澤，澤在地上，聚水之象，從爻畫看，《萃》九五居中得正，上下眾陰皆應，故有聚會之義。聚而上者謂之升：是說反《萃》而成《升》，坤為眾，《萃》卦坤眾聚於下，《升》卦坤眾在上，故曰“聚而上者謂之升”。聚，指坤眾而言。升，有上升之義。《升》下巽上坤，巽為木，坤為地，地中生木，日長而升高，故有上升之義。</p><p>⑨困：窮困。《困》下坎上兌，坎為水，兌為澤，水在澤下，水下漏而上乾枯，故有窮困之義。困乎上者：指《困》卦水在澤下，澤上無水而窮困。必反下：反《困》成《井》，《困》兌澤到下，成巽木，而成《井》。故曰“反下”。井，有養之義。井道不可不革：即《繫辭》所謂“居其所而遷”。即井能出水而利民，故曰“不可不革”。革，本指獸皮治去其毛此指變革。《革》卦下離上兌，兌為澤，離為火，澤火相息，故有變革之義。</p><p>⑩鼎：本指古代一種烹飪器和禮器，因鼎烹飪以成新物，故有取新之義。《雜卦》：“鼎，取新也。”故曰“革物莫若鼎”。《鼎》下巽上離，離為火，巽為木。木上有火，鼎烹飪之象。主器者：主管祭祀人。器，指鼎。主器者莫若長子：是指由長子主管祭祀。古代宗法世襲制度，王侯大夫之國與邑，原則上由長子繼承，故長子掌管祭祀。震為長子。</p><p>⑾物不可終動：指反《震》成《艮》。屈萬里《讀易三種》：“岳珂九經三傳沿革例，如《易序卦》‘不可以終動，動必止之’，諸本無‘動必，二字，惟蜀本；興國本有之。”止，不動。《艮》上下皆艮，即上下不動，故曰止。漸，有漸進之義。《漸》下艮上巽，艮為山，巽木，為木生山上漸漸增高，故漸為“進”。進必有所歸：指反《漸》成《歸妹》。古代女子出嫁，按六禮進行，成婚過程稱為漸，成婚為歸妹。歸，嫁。《歸妹》下兌上震，震為長男，兌為少女，有少女歸長男之象。</p><p>⑿豐：豐大之義。《豐》下離上震，震為雷，離為電，雷電至，威嚴而光明，豐有“大”義。旅：旅行。《旅》下艮上離，艮為山，離為火，山上有火，火行而不停。故有行之義。又內卦艮山靜止為主，外卦火動為客，山不動如館舍，火動不止如旅客，故旅有旅行之義。</p><p>⒀旅而無所容：旅客行動而無所容身。巽：帛《易》作“筭”，本指計算工具，此訓為“入”，《巽》兩巽相重，巽為風，風相隨，風吹無所不入，故有“入”之義。兌：有歡悅之義，兌為口，故亦為“說”，通悅。</p><p>⒁渙：離散。《渙》下坎上巽，坎為水，巽為風，風行水上，將水衝散，故渙有“離”之義。離：散。節：節度。《節》卦下兌上坎，兌為澤，坎為水，澤上有水，其容量有限度，故節有節度之義。節而信之：節制而有誠信。中孚，中有孚信。《中孚》下兌上巽，巽為風，兌為澤，風令行於上，澤惠施於下，上下感應，有中孚之義。從爻畫看，《中孚》＄上下二陽，中為二陰，內虛外實，心虛而有實，故為中孚。</p><p>⒂小過：小的經過。《小過》下艮上震，艮為山，震為雷，雷在山上，故有小過之象，從爻畫看，《小過》上下各二陰，中間二陽，有二陰經過二陽之義。陰為小，故曰小過。此“過”不是過失而是經過。濟：渡過，引申為成功。既濟：指已成功。《既濟》下離上坎，坎為水，離為火，水火相互交通，各得其用，故為“既濟”之義。未濟，未渡過，引申為未成功。《未濟》與《既濟》相反，為水火不相交，故有“未濟”之義。</p>',39)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
